void vrtc_f_user_service( void *dummy , Vrtc_F vrtc_f )
{
    Exec_Q_Msg *exec_q_msg ; 

	if( vrtc_f->irq )
	{
		vrtc_f->irq = FALSE ; 

		remove_exec_q:
		{
			exec_q_msg = exec_q_remove( vrtc_q );
		
			if( exec_q_msg )
			{
				exec_q_insert( exec_q_msg , vrtc_f->exec_func , vrtc_f );
			}
			else
			{
				if( exec_q_free_add( vrtc_q  , sizeof( Exec_Q_Msg ) ) )
				{
                    goto remove_exec_q ; 
				};
			};
		};
	};		
}

